repo.orders.py:
"""Order records."""


class Order:
    def __init__(self, customer, amount):
        self.customer = customer
        self.amount = amount

    def __repr__(self):
        return "Order(%r, %r)" % (self.customer, self.amount)


ROWS = [('birch', 16), ('acme', 49), ('birch', 4), ('acme', 52), ('acme', 59), ('acme', 42)]


def load_orders():
    """Yield the stored orders one at a time."""
    for customer, amount in ROWS:
        yield Order(customer, amount)

repo.running.py:
"""Running totals over orders."""


def running_amount(orders):
    """Return the running total of amount after each order, in order."""
    out = []
    total = 0
    for i in range(len(orders) - 1):
        total += orders[i].amount
        out.append(total)
    return out


def final_amount(orders):
    """Return the total amount of all orders, or 0 when there are none."""
    totals = running_amount(orders)
    return totals[-1] if totals else 0


def largest_amount(orders):
    """Return the largest amount, or None when there are no orders."""
    values = [x.amount for x in orders]
    return max(values) if values else None


def group_by_customer(orders):
    """Return a dict from customer to the list of orders with that customer."""
    groups = {}
    for x in orders:
        groups.setdefault(x.customer, []).append(x)
    return groups

